      select.innerHTML = keys.map((k) => `<option>${k}</option>`).join("");
      const out = document.getElementById("out");
      function report() {
        const p = getComputedStyle(document.getElementById("pressed"));
        const s = getComputedStyle(document.getElementById("secondary"));
        out.textContent = `pressed bg: ${p.backgroundColor}\npressed border: ${p.borderTopColor}\npressed text: ${p.color}\nsecondary bg: ${s.backgroundColor}`;
      }
      select.addEventListener("change", () => {
        document.documentElement.dataset.pantokenColor = select.value;
        requestAnimationFrame(report);
      });
      document.getElementById("dark").addEventListener("change", (e) => {
        document.documentElement.style.colorScheme = e.target.checked ? "dark" : "light";
        requestAnimationFrame(report);
      });
      document.documentElement.style.colorScheme = "light";
      report();
    </script>
