{"content": "// Builds a standalone demo of the custom-theme-colors brand relinking fix.
// Not part of the repo build — run from anywhere: node /tmp/pt-demo-build.mjs
import { mkdirSync, writeFileSync, readFileSync, rmSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { join } from "node:path";

const REPO = "/Users/dwahl/Scripts/pantoken";
const PLUGIN = join(REPO, "plugins/pantoken/custom-theme-colors");
const OUT = "/Users/dwahl/Desktop/pantoken-theme-color-demo";

mkdirSync(OUT, { recursive: true });

// "After" CSS from the current working tree.
const { customThemeColorsCss } = await import(pathToFileURL(join(PLUGIN, "src/index.ts")).href);
writeFileSync(join(OUT, "theme-colors.after.css"), customThemeColorsCss());

// "Before" CSS from the last commit, so the demo can show the bug side by side.
const beforeSrc = execFileSync("git", ["show", "HEAD:plugins/pantoken/custom-theme-colors/src/index.ts"], {
  cwd: REPO,
  encoding: "utf8",
});
const beforePath = join(PLUGIN, "src/__demo_before.ts");
writeFileSync(beforePath, beforeSrc);
try {
  const before = await import(pathToFileURL(beforePath).href);
  writeFileSync(join(OUT, "theme-colors.before.css"), before.customThemeColorsCss());
} finally {
  rmSync(beforePath, { force: true });
}

const copy = (from, to) => writeFileSync(join(OUT, to), readFileSync(join(REPO, from)));
copy("formats/css/dist/style.lean.css", "tokens.css");
copy("formats/components/dist/base.css", "base.css");
copy("formats/components/dist/components.css", "components.css");

console.log("demo assets written to", OUT);
