:root {
  color-scheme: light;
}

body {
  margin: 0;
  padding: 0 0 4rem;
  font-family: var(--instui-font-family-base, system-ui, sans-serif);
  background: var(--instui-color-background-secondary, #f5f5f5);
  color: var(--instui-color-text-body, #2d3b45);
}

.bar {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1.5rem;
  background: var(--instui-color-background-primary, #fff);
  border-bottom: 1px solid var(--instui-color-stroke-base, #c7cdd1);
}

.bar__title {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.bar__title span {
  opacity: 0.7;
  font-size: 0.875rem;
}

.bar__controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
}

.swatches {
  display: flex;
  gap: 0.25rem;
}

.swatches button {
  width: 1.75rem;
  height: 1.75rem;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  display: grid;
  place-items: center;
}

.swatches button[aria-pressed="true"] {
  border-color: currentcolor;
}

.swatches span {
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.15);
}

.toggles {
  display: flex;
  gap: 1rem;
}

.switch {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.875rem;
  cursor: pointer;
  user-select: none;
}

.lede {
  max-width: 62ch;
  margin: 1.5rem auto 0;
  padding: 0 1.5rem;
  line-height: 1.6;
}

main {
  max-width: 68rem;
  margin: 0 auto;
  padding: 0 1.5rem;
}

section {
  margin-top: 2.5rem;
  padding: 1.5rem;
  border-radius: 12px;
  background: var(--instui-color-background-primary, #fff);
  border: 1px solid var(--instui-color-stroke-base, #c7cdd1);
}

section h2 {
  margin: 0 0 0.5rem;
  font-size: 1.25rem;
}

section h3 {
  margin: 1.75rem 0 0.5rem;
  font-size: 0.8125rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.6;
}

.note {
  margin: 0;
  max-width: 78ch;
  font-size: 0.875rem;
  line-height: 1.6;
  opacity: 0.8;
}

.note code {
  font-size: 0.8125em;
  padding: 0.05em 0.3em;
  border-radius: 4px;
  background: rgb(127 127 127 / 0.15);
}

.row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.row--airy {
  gap: 1.5rem;
  padding: 1rem 0.5rem;
}

.demo-card {
  display: grid;
  gap: 0.25rem;
  padding: 1.25rem 1.5rem;
  min-width: 10rem;
}

.demo-card span {
  font-size: 0.75rem;
  opacity: 0.6;
}

.demo-popover {
  padding: 1rem 1.25rem;
  max-width: 18rem;
}

/* Checkerboard so a baked alpha is visible rather than blending into the card. */
.chips {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(17rem, 1fr));
  gap: 0.75rem;
  margin-top: 0.75rem;
}

.chip {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.75rem;
  line-height: 1.4;
  word-break: break-all;
}

.chip__paint {
  flex: none;
  width: 3rem;
  height: 2.25rem;
  border-radius: 6px;
  border: 1px solid rgb(127 127 127 / 0.35);
  background-image:
    linear-gradient(45deg, #ccc 25%, transparent 25%),
    linear-gradient(-45deg, #ccc 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #ccc 75%),
    linear-gradient(-45deg, transparent 75%, #ccc 75%);
  background-size: 10px 10px;
  background-position: 0 0, 0 5px, 5px -5px, -5px 0;
}

.chip__paint > i {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 5px;
  background: var(--paint);
}

.chart {
  display: flex;
  margin-top: 0.75rem;
  border-radius: 6px;
  overflow: hidden;
  height: 2.5rem;
}

.chart > i {
  flex: 1;
  background: var(--paint);
}

.readout {
  width: 100%;
  margin-top: 0.75rem;
  border-collapse: collapse;
  font-size: 0.8125rem;
}

.readout th,
.readout td {
  text-align: left;
  padding: 0.375rem 0.5rem;
  border-bottom: 1px solid rgb(127 127 127 / 0.2);
}

.readout td:last-child {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
