{"content": "const COLORS = [
  "navy",
  "blue",
  "green",
  "red",
  "orange",
  "grey",
  "plum",
  "violet",
  "stone",
  "sky",
  "honey",
  "sea",
  "aurora",
];

// The tokens the relinking pass rewrites.
const RELINKED = [
  "--instui-color-background-interactive-action-secondary-base",
  "--instui-color-background-interactive-action-secondary-hover",
  "--instui-color-background-interactive-action-secondary-active",
  "--instui-color-stroke-interactive-action-secondary-base",
  "--instui-color-stroke-interactive-action-secondary-hover",
  "--instui-color-stroke-interactive-action-secondary-active",
  "--instui-color-drop-shadow-shadow-color1",
  "--instui-color-drop-shadow-shadow-color2",
  "--instui-color-institutional-brand-button-secondary-bgd",
  "--instui-component-base-button-primary-ghost-active-background",
  "--instui-component-base-button-primary-ghost-border-color",
  "--instui-component-base-button-primary-ghost-hover-background",
  "--instui-component-base-button-secondary-background",
  "--instui-component-base-button-secondary-border-color",
  "--instui-component-base-button-secondary-hover-border-color",
  "--instui-component-base-button-secondary-active-border-color",
  "--instui-component-base-button-secondary-ghost-border-color",
  "--instui-component-base-button-tertiary-hover-border-color",
  "--instui-component-base-button-tertiary-active-border-color",
];

// On the preservation list — these must stay blue.
const PRESERVED = [
  "--instui-color-background-accent-blue",
  "--instui-color-stroke-accent-blue",
  "--instui-color-text-accent-blue",
  "--instui-color-icon-accent-blue",
  "--instui-component-avatar-blue-background-color",
];

const root = document.documentElement;

function chip(name) {
  const el = document.createElement("div");
  el.className = "chip";
  el.innerHTML = `<span class="chip__paint" style="--paint: var(${name})"><i></i></span><code>${name}</code>`;
  return el;
}

function buildSwatches() {
  const host = document.getElementById("swatches");
  host.innerHTML = COLORS.map(
    (c) =>
      `<button type="button" data-color="${c}" aria-pressed="${c === "navy"}" title="${c}" aria-label="${c}">` +
      `<span style="background: var(--instui-primitive-color-${c}-${c}70)"></span></button>`,
  ).join("");

  host.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-color]");
    if (!button) return;
    root.dataset.pantokenColor = button.dataset.color;
    for (const other of host.querySelectorAll("button")) {
      other.setAttribute("aria-pressed", String(other === button));
    }
    report();
  });
}

function buildChips() {
  const host = document.getElementById("chips");
  for (const name of RELINKED) host.append(chip(name));

  const accents = document.getElementById("accent-chips");
  for (const name of PRESERVED) accents.append(chip(name));

  const chart = document.getElementById("chart");
  chart.innerHTML = Array.from(
    { length: 10 },
    (_, i) => `<i style="--paint: var(--instui-color-background-chart-sequential-blue-color${i})"></i>`,
  ).join("");
}

function report() {
  const rows = [
    ["Toggle, pressed — background", '.instui-button.-toggle[aria-pressed="true"]', "backgroundColor"],
    ["Toggle, pressed — border", '.instui-button.-toggle[aria-pressed="true"]', "borderTopColor"],
    ["Toggle, pressed — text", '.instui-button.-toggle[aria-pressed="true"]', "color"],
    ["Secondary button — background", ".instui-button.-color-secondary", "backgroundColor"],
    ["Elevated view — shadow", ".instui-view.-shadow-above", "boxShadow"],
    ["Inline info alert — background", ".instui-alert.-color-info", "backgroundColor"],
  ];

  document.getElementById("readout").innerHTML = rows
    .map(([label, selector, prop]) => {
      const node = document.querySelector(selector);
      const value = node ? getComputedStyle(node)[prop] : "—";
      return `<tr><td>${label}</td><td>${value}</td></tr>`;
    })
    .join("");
}

document.getElementById("fix").addEventListener("change", (event) => {
  const on = event.target.checked;
  document.getElementById("css-after").disabled = !on;
  document.getElementById("css-before").disabled = on;
  requestAnimationFrame(report);
});

document.getElementById("dark").addEventListener("change", (event) => {
  root.style.colorScheme = event.target.checked ? "dark" : "light";
  requestAnimationFrame(report);
});

buildSwatches();
buildChips();
root.style.colorScheme = "light";
report();
