{"content": "// Literal step-70 hex, not var() — the navy and blue primitives are themselves remapped,
// so a var()-painted swatch would always show the selected color.
const COLORS = {
  navy: "#7097C7",
  blue: "#4798E3",
  green: "#3EA75B",
  red: "#F56050",
  orange: "#F16824",
  grey: "#8D959F",
  plum: "#E665B4",
  violet: "#B680CC",
  stone: "#949494",
  sky: "#349ED2",
  honey: "#BE8A01",
  sea: "#04A4B7",
  aurora: "#03A879",
};

// Brand surfaces that follow the selected swatch.
const BRAND_TOKENS = {
  Backgrounds: [
    "--instui-color-background-brand",
    "--instui-color-background-opacity",
    "--instui-color-background-interactive-action-primary-base",
    "--instui-color-background-interactive-action-primary-hover",
    "--instui-color-background-interactive-action-secondary-base",
    "--instui-color-background-interactive-action-secondary-active",
    "--instui-color-background-interactive-action-tertiary-hover",
    "--instui-color-background-interactive-action-primary-on-color-hover",
  ],
  Strokes: [
    "--instui-color-stroke-brand",
    "--instui-color-stroke-interactive-focus-ring-base",
    "--instui-color-stroke-interactive-action-primary-base",
    "--instui-color-stroke-interactive-action-secondary-base",
    "--instui-color-stroke-interactive-action-tertiary-base",
    "--instui-color-stroke-interactive-action-secondary-on-color-hover",
  ],
  Text: [
    "--instui-color-text-interactive-navigation-primary-base",
    "--instui-color-text-interactive-navigation-primary-hover",
    "--instui-color-text-interactive-action-primary-base",
    "--instui-color-text-interactive-action-secondary-base",
    "--instui-color-text-interactive-action-tertiary-base",
    "--instui-color-text-interactive-action-primary-on-color-base",
  ],
  Icons: [
    "--instui-color-icon-brand",
    "--instui-color-icon-interactive-action-primary-base",
    "--instui-color-icon-interactive-action-secondary-base",
    "--instui-color-icon-interactive-navigation-primary-base",
    "--instui-color-icon-interactive-navigation-primary-on-color-base",
  ],
  Elevation: [
    "--instui-color-drop-shadow-shadow-color1",
    "--instui-color-drop-shadow-shadow-color2",
  ],
  "Canvas institutional": [
    "--instui-color-institutional-brand-primary",
    "--instui-color-institutional-link-color",
    "--instui-color-institutional-brand-button-primary-bgd",
    "--instui-color-institutional-brand-button-secondary-bgd",
    "--instui-color-institutional-global-nav-link-hover",
  ],
};

// Pinned regardless of the selected swatch.
const PINNED = [
  "--instui-color-background-accent-blue",
  "--instui-color-stroke-accent-blue",
  "--instui-color-text-accent-blue",
  "--instui-color-icon-accent-blue",
