// so the demo keeps the lean token stylesheet instead of shipping all 1892 glyphs.
import { readFileSync, writeFileSync } from "node:fs";

const SOURCE = "/Users/dwahl/Scripts/pantoken/formats/css/dist/style.css";
const OUT = "/Users/dwahl/Desktop/pantoken-theme-color-demo/icon-tokens.css";

const NEEDED = [
  // component defaults (component-icons.css)
  "check",
  "chevron-down",
  "chevron-left",
  "chevron-right",
  "chevron-up",
  "circle-alert",
  "circle-check",
  "circle-x",
  "info",
  "minus",
  "triangle-alert",
  "x",
  // used directly in the demo markup
  "house",
  "inbox",
  "calendar",
  "external-link",
];

const css = readFileSync(SOURCE, "utf8");
const found = [];
const missing = [];

for (const name of NEEDED) {
  const match = new RegExp(`--instui-icon-${name}:\\s*([^;}]+)`, "u").exec(css);
  if (match) found.push(`  --instui-icon-${name}: ${match[1].trim()};`);
  else missing.push(name);
}

writeFileSync(OUT, `:root {\n${found.join("\n")}\n}\n`);
console.log(`wrote ${found.length} glyphs`);
if (missing.length) console.log("missing:", missing.join(", "));
